package com.honorablemobile

import org.junit.runner.RunWith
import org.robolectric.RobolectricTestRunner
import org.robolectric.annotation.Config

import android.app.AlertDialog
import android.net.Uri
import app.honorable.editor.EditorAccessMode
import org.junit.Assert.*
import org.junit.Test

/** Real visible-approval/project mutation gates, with metadata-only dialog membership. */
@RunWith(RobolectricTestRunner::class)
@Config(sdk = [34], manifest = Config.NONE, application = android.app.Application::class)
class VideoMomentNoteControlsReviewTest {
 private val unsafe=JvmTestAllocator
 private fun set(a:Any,n:String,v:Any?)=a.javaClass.getDeclaredField(n).apply{isAccessible=true}.set(a,v)
 private fun get(a:Any,n:String)=a.javaClass.getDeclaredField(n).apply{isAccessible=true}.get(a)
 private fun call(a:Any,n:String,vararg args:Any?)=a.javaClass.declaredMethods.single{it.name==n&&it.parameterCount==args.size}.apply{isAccessible=true}.invoke(a,*args)
 private fun activity()=(unsafe.allocateInstance(HonorableVideoEditorActivity::class.java)as HonorableVideoEditorActivity).also{val p=VideoEditProject(5000);p.restore(listOf(VideoSegment(0,5000,captions=listOf(VideoCaption(0,500,"A"),VideoCaption(1000,1500,"B")),captionSourceUri="content://synthetic/subtitles")),soundtrack=VideoSoundtrack("content://synthetic/music",10000,loop=false));set(it,"project",p);set(it,"source",Uri.parse("content://synthetic/video"));set(it,"primaryDurationMs",5000L);set(it,"accessMode",EditorAccessMode.GUEST_BASIC);set(it,"workspaceActive",true);set(it,"importedSources",linkedMapOf<String,VideoSource>())}
 private fun showing(d:AlertDialog,value:Boolean){android.app.Dialog::class.java.getDeclaredField("mDecor").apply{isAccessible=true}.set(d,if(value)unsafe.allocateInstance(android.view.View::class.java)else null)}
 private fun dialog()=(unsafe.allocateInstance(AlertDialog::class.java)as AlertDialog).also{showing(it,true)}
 private fun capture(a:HonorableVideoEditorActivity)=call(a,"captureCaptionReview")as VideoCaptionReviewState
 private fun fixture():Triple<HonorableVideoEditorActivity,AlertDialog,VideoActionReview>{val a=activity();val d=dialog();val r=VideoActionReview();r.open(d);set(a,"momentReviewRequest",r);set(a,"momentReviewDialog",d);set(a,"captionReviewDialogs",linkedSetOf(d));return Triple(a,d,r)}
 private fun perform(a:HonorableVideoEditorActivity,d:AlertDialog,r:VideoActionReview,review:VideoCaptionReviewState,action:(()->Unit)->Unit)=call(a,"performMomentReview",d,r,review,action)as Boolean
 @Test fun successorSurvivesLatePredecessorDismiss(){val r=VideoActionReview();val old=Any();val next=Any();assertTrue(r.open(old));assertTrue(r.open(next));r.dismiss(old);assertTrue(r.owns(next));assertFalse(r.owns(old));r.dismiss(next);assertTrue(r.isClosed)}
 @Test fun approvalIsConsumedBeforeGuardAndOnlyOnce(){val r=VideoActionReview();val d=Any();r.open(d);var calls=0;assertTrue(r.execute(d,{assertFalse(r.owns(d));assertTrue(r.isExecuting(d))}){calls++});assertFalse(r.isExecuting(d));assertFalse(r.execute(d,{fail("guard")}){calls++});assertEquals(1,calls);assertFalse(r.open(Any()))}
 @Test fun failedGuardConsumesApprovalWithoutSideEffect(){val r=VideoActionReview();val d=Any();r.open(d);try{r.execute(d,{error("stale")}){fail("write")};fail("accepted")}catch(_:IllegalStateException){};assertTrue(r.isClosed);assertFalse(r.isExecuting(d))}
 @Test fun failureClearsExecutionPermission(){val r=VideoActionReview();val d=Any();r.open(d);try{r.execute(d,{}){error("IO")};fail("accepted")}catch(_:IllegalStateException){};assertFalse(r.isExecuting(d));assertTrue(r.isClosed)}
 @Test fun foreignStageCannotConsumeCurrent(){val r=VideoActionReview();val d=Any();r.open(d);assertFalse(r.execute(Any(),{fail("guard")}){fail("write")});assertTrue(r.owns(d))}
 @Test fun closeRevokesGuardWhileActionIsRunning(){val r=VideoActionReview();val d=Any();r.open(d);r.execute(d,{}){assertTrue(r.isExecuting(d));r.close();assertFalse(r.isExecuting(d))};assertTrue(r.isClosed)}
 @Test fun actualActivityExecutesGuardedActionOnce(){val(a,d,r)=fixture();val review=capture(a);var calls=0;var retained:(()->Unit)?=null;assertTrue(perform(a,d,r,review){guard->guard();retained=guard;calls++;guard()});assertEquals(1,calls);assertFalse(perform(a,d,r,review){calls++});try{retained!!();fail("guard survived") }catch(e:IllegalStateException){};assertEquals(1,calls)}
 @Test fun staleForegroundSourceDurationGenerationAndSessionCannotExecute(){for(flag in listOf("pause","source","duration","generation","mode","busy","recovery","analysis")){val(a,d,r)=fixture();val review=capture(a);when(flag){"pause"->set(a,"workspaceActive",false);"source"->set(a,"source",Uri.parse("content://synthetic/other"));"duration"->set(a,"primaryDurationMs",5001L);"generation"->set(a,"captionReviewGeneration",review.generation+1);"mode"->set(a,"accessMode",EditorAccessMode.ACCOUNT);"busy"->set(a,"saving",true);"recovery"->set(a,"recoveryBytes",byteArrayOf(1));else->set(a,"analyzing",true)};assertFalse(flag,perform(a,d,r,review){fail("write")});assertFalse((get(a,"project")as VideoEditProject).canUndo)}}
 @Test fun oldDialogAndRequestCannotConsumeNewOwner(){val(a,old,r)=fixture();val review=capture(a);val newer=dialog();val next=VideoActionReview();next.open(newer);set(a,"momentReviewRequest",next);set(a,"momentReviewDialog",newer);set(a,"captionReviewDialogs",linkedSetOf(newer));assertFalse(perform(a,old,r,review){fail("write")});assertTrue(next.owns(newer));assertTrue(perform(a,newer,next,review){it()})}
 @Test fun hiddenAndUntrackedDialogsCannotWrite(){for(flag in listOf("hidden","untracked")){val(a,d,r)=fixture();val review=capture(a);if(flag=="hidden")showing(d,false)else set(a,"captionReviewDialogs",linkedSetOf<AlertDialog>());assertFalse(perform(a,d,r,review){fail("write")})}}
 @Test fun invalidLabelAndDuplicateTimePrevalidationRemainRetryable(){val r=VideoActionReview();val d=Any();r.open(d);val note=VideoMomentNote(1000,"First");val catalog=VideoMomentNotes(5000,listOf(note));assertTrue(runCatching{VideoMomentNote(2000,"")}.isFailure);assertTrue(r.owns(d));assertTrue(runCatching{catalog.add(note.copy(label="Duplicate time"))}.isFailure);assertTrue(r.owns(d));assertEquals(2,catalog.add(VideoMomentNote(2000,"Corrected")).notes.size);assertTrue(r.execute(d,{}){})}
 @Test fun noteCatalogLatestMergeRenameDeleteAndCodecRemainExact(){val first=VideoMomentNote(1000,"First");val second=VideoMomentNote(3000,"Second");val catalog=VideoMomentNotes(5000,listOf(first));val latest=catalog.add(second);val renamed=latest.rename(first,"Renamed");assertEquals(listOf(first.copy(label="Renamed"),second),renamed.notes);assertEquals(listOf(second),renamed.remove(first.copy(label="Renamed")).notes);assertTrue(runCatching{renamed.remove(first)}.isFailure);assertEquals(renamed,VideoMomentCodec.decode(VideoMomentCodec.encode(renamed)));assertEquals(listOf(first),catalog.notes)}
 @Test fun approvedNoteActionKeepsProjectAndHistoryUntouched(){val(a,d,r)=fixture();val p=get(a,"project")as VideoEditProject;val clips=p.segments;val music=p.soundtrack;var stored=VideoMomentNotes(5000);val review=capture(a);assertTrue(perform(a,d,r,review){guard->guard();stored=stored.add(VideoMomentNote(1000,"Saved"));guard()});assertEquals(listOf(VideoMomentNote(1000,"Saved")),stored.notes);assertSame(clips,p.segments);assertSame(music,p.soundtrack);assertFalse(p.canUndo);assertFalse(perform(a,d,r,review){fail("duplicate write")})}
 @Test fun lifecycleClosesLeaseAndPausedEntryReturnsBeforeStorageOrWidgets(){val(a,d,r)=fixture();set(a,"captionReviewDialogs",linkedSetOf<AlertDialog>());call(a,"invalidateCaptionReviews");assertTrue(r.isClosed);assertNull(get(a,"momentReviewRequest"));assertNull(get(a,"momentReviewDialog"));for(flag in listOf("pause","busy","recovery")){val b=activity();when(flag){"pause"->set(b,"workspaceActive",false);"busy"->set(b,"saving",true);else->set(b,"recoveryBytes",byteArrayOf(1))};call(b,"momentNotes");assertNull(get(b,"momentReviewRequest"));assertNull(get(b,"captionReviewDialogs"))}}
 @Test fun changedOrDeletedNoteRefusesJumpBeforeSideEffectAndConsumesApproval(){val note=VideoMomentNote(1000,"Old");for(current in listOf(VideoMomentNotes(5000),VideoMomentNotes(5000,listOf(note.copy(label="Renamed"))))){val(a,d,r)=fixture();val review=capture(a);var jumps=0;try{perform(a,d,r,review){guard->check(current.notes.contains(note)){"Note changed"};guard();jumps++};fail("accepted stale note")}catch(e:java.lang.reflect.InvocationTargetException){assertTrue(e.cause is IllegalStateException)};assertEquals(0,jumps);assertTrue(r.isClosed);assertFalse(perform(a,d,r,review){jumps++})}}
 @Test fun lateMomentActionCannotCloseOrConsumeAnIndependentLookOwner(){val(a,d,r)=fixture();val review=capture(a);val look=VideoLookReview();val lookDialog=dialog();look.open(lookDialog);set(a,"lookReviewRequest",look);set(a,"lookReviewDialog",lookDialog);set(a,"workspaceActive",false);assertFalse(perform(a,d,r,review){fail("write")});assertTrue(look.owns(lookDialog));assertSame(look,get(a,"lookReviewRequest"));assertSame(lookDialog,get(a,"lookReviewDialog"))}
}
